const script = String.raw`
const fs = require('fs');
const ASAR = 'D:\\Users\\jjq21\\AppData\\Local\\Programs\\DeepSeek Harness\\resources\\app.asar';
const head = Buffer.alloc(16);
const fd = fs.openSync(ASAR, 'r');
fs.readSync(fd, head, 0, 16, 0);
const jsonSize = head.readUInt32LE(12);
const jbuf = Buffer.alloc(jsonSize);
fs.readSync(fd, jbuf, 0, jsonSize, 16);
const dir = JSON.parse(jbuf.toString('utf8'));
const dataStart = 16 + jsonSize;
function find(node, prefix, name) {
 for (const k of Object.keys(node.files || {})) {
 const v = node.files[k];
 const p = prefix ? prefix + '/' + k : k;
 if (k === name && !v.files) return v;
 if (v.files) { const r = find(v, p, name); if (r) return r; }
 }
 return null;
}
const wanted = process.argv.slice(2);
const outDir = 'C:\\Users\\jjq21\\AppData\\Local\\Temp\\ofm-docs';
fs.mkdirSync(outDir, { recursive: true });
for (const w of wanted) {
 const [pkgPath, fileName] = w.split('::');
 const entry = find(dir, '', '');
 // resolve nested path
 let node = dir;
 for (const seg of (pkgPath + '/' + fileName).split('/')) {
 if (!node.files || !node.files[seg]) { node = null; break; }
 node = node.files[seg];
 }
 if (!node || node.files) { console.log('MISS ' + w); continue; }
 const b = Buffer.alloc(node.size);
 fs.readSync(fd, b, 0, node.size, dataStart + parseInt(node.offset, 10));
 const dest = outDir + '\\' + pkgPath.split('/').slice(-1)[0] + '__' + fileName.replace(/[^A-Za-z0-9._-]/g, '_');
 fs.writeFileSync(dest, b);
 console.log('OK -> ' + dest + ' (' + node.size + ' bytes)');
}
fs.closeSync(fd);
`;
await tools.write({ file_path: "C:\\Users\\jjq21\\AppData\\Local\\Temp\\ofm-extract.cjs", content: script });
const paths = [
 "dsh/node_modules/@deepseek-ai/dsh-client-ui-sidebar::README.zh.md",
 "dsh/node_modules/@deepseek-ai/dsh-client-ui-workspace::README.zh.md",
 "dsh/node_modules/@deepseek-ai/dsh-client-ui-slots::README.zh.md",
 "dsh/node_modules/@deepseek-ai/dsh-client-ui-layout::README.zh.md",
];
const r = await tools.pwsh({ command: `& 'C:\\Program Files\\nodejs\\node.exe' 'C:\\Users\\jjq21\\AppData\\Local\\Temp\\ofm-extract.cjs' ${paths.map(p => `"${p}"`).join(" ")}`, description: "Extract package README docs from asar" });
